import{_ as t,o as e,c as a,Q as o}from"./chunks/framework.48927342.js";const g=JSON.parse('{"title":"Lost Property and Collection at the Police Station","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/dialogues/02-lost-property.md","filePath":"en/more/maltese/practice/dialogues/02-lost-property.md"}'),d={name:"en/more/maltese/practice/dialogues/02-lost-property.md"},r=o('<h1 id="lost-property-and-collection-at-the-police-station" tabindex="-1">Lost Property and Collection at the Police Station <a class="header-anchor" href="#lost-property-and-collection-at-the-police-station" aria-label="Permalink to &quot;Lost Property and Collection at the Police Station&quot;">​</a></h1><p><strong>Scenario:</strong> Mark answers Anna&#39;s call at the police station. They identify her wallet and arrange a collection time.</p><h2 id="complete-dialogue" tabindex="-1">Complete Dialogue <a class="header-anchor" href="#complete-dialogue" aria-label="Permalink to &quot;Complete Dialogue&quot;">​</a></h2><p><strong>Anna:</strong> Bonġu. Sibtu kartiera mitlufa ħdejn il-waqfa tal-karozzi tal-linja?</p><p><strong>Mark:</strong> Iva, il-kartiera tinsab hawn fl-għassa tal-pulizija.</p><p><strong>Anna:</strong> X&#39;nagħmel biex niġi niġborha?</p><p><strong>Mark:</strong> Tista&#39; tiġi l-għassa għada filgħodu.</p><p><strong>Anna:</strong> Nista&#39; niġi fid-disgħa?</p><p><strong>Mark:</strong> Iva. Ġib miegħek dokument ta&#39; identità.</p><p><strong>Anna:</strong> Se jkolli bżonn inġib xi prova oħra?</p><p><strong>Mark:</strong> Le, id-dokument tal-identità jkun biżżejjed.</p><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><h3 id="_1-anna-owner-of-the-lost-item" tabindex="-1">1. Anna (Owner of the Lost Item) <a class="header-anchor" href="#_1-anna-owner-of-the-lost-item" aria-label="Permalink to &quot;1. Anna (Owner of the Lost Item)&quot;">​</a></h3><p><strong>Malti:</strong> Bonġu. Sibtu kartiera mitlufa ħdejn il-waqfa tal-karozzi tal-linja?</p><p><strong>Translation:</strong> Hello. Did you find a lost wallet near the bus stop?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Bonġu</td><td>hello</td><td>Greeting</td></tr><tr><td>Sibtu</td><td>did you find it?</td><td><code>sibt</code> is the find-form interpreted from context; <code>-u</code> can refer to a masculine object (“it”)</td></tr><tr><td>kartiera</td><td>wallet</td><td>Feminine noun</td></tr><tr><td>mitlufa</td><td>lost</td><td>Feminine singular form agreeing with <code>kartiera</code></td></tr><tr><td>ħdejn</td><td>beside; near</td><td>Preposition of location</td></tr><tr><td>il-waqfa</td><td>the stop</td><td>Feminine noun with the definite article</td></tr><tr><td>tal-karozzi</td><td>of the cars</td><td><code>ta&#39;</code> contracts with the article; <code>karozzi</code> is plural</td></tr><tr><td>tal-linja</td><td>of the line</td><td>Contracted <code>ta&#39; + il-linja</code>; <code>karozzi tal-linja</code> means “bus”</td></tr></tbody></table><h3 id="_2-mark-police-officer" tabindex="-1">2. Mark (Police Officer) <a class="header-anchor" href="#_2-mark-police-officer" aria-label="Permalink to &quot;2. Mark (Police Officer)&quot;">​</a></h3><p><strong>Malti:</strong> Iva, il-kartiera tinsab hawn fl-għassa tal-pulizija.</p><p><strong>Translation:</strong> Yes, the wallet is here at the police station.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Iva</td><td>yes</td><td>Affirmative response</td></tr><tr><td>il-kartiera</td><td>the wallet</td><td>Definite article + <code>kartiera</code></td></tr><tr><td>tinsab</td><td>is located; is</td><td>Form used with a feminine subject</td></tr><tr><td>hawn</td><td>here</td><td>Place adverb</td></tr><tr><td>fl-għassa</td><td>at the station</td><td>Contracted <code>f&#39;</code> “at” + <code>l-għassa</code></td></tr><tr><td>tal-pulizija</td><td>of the police</td><td>Contracted <code>ta&#39; + il-pulizija</code></td></tr></tbody></table><h3 id="_3-anna-owner-of-the-lost-item" tabindex="-1">3. Anna (Owner of the Lost Item) <a class="header-anchor" href="#_3-anna-owner-of-the-lost-item" aria-label="Permalink to &quot;3. Anna (Owner of the Lost Item)&quot;">​</a></h3><p><strong>Malti:</strong> X&#39;nagħmel biex niġi niġborha?</p><p><strong>Translation:</strong> What should I do to come and collect it?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>X&#39;</td><td>what; how</td><td>Short form of <code>xiex</code></td></tr><tr><td>nagħmel</td><td>I do</td><td>First-person singular form</td></tr><tr><td>biex</td><td>in order to; so that</td><td>Introduces a purpose or following action</td></tr><tr><td>niġi</td><td>I come</td><td>First-person singular form</td></tr><tr><td>niġborha</td><td>I collect it; retrieve it</td><td><code>niġbor</code> “I collect” + <code>-ha</code> “it” (feminine)</td></tr></tbody></table><h3 id="_4-mark-police-officer" tabindex="-1">4. Mark (Police Officer) <a class="header-anchor" href="#_4-mark-police-officer" aria-label="Permalink to &quot;4. Mark (Police Officer)&quot;">​</a></h3><p><strong>Malti:</strong> Tista&#39; tiġi l-għassa għada filgħodu.</p><p><strong>Translation:</strong> You can come to the station tomorrow morning.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tista&#39;</td><td>you can</td><td>Second-person singular form</td></tr><tr><td>tiġi</td><td>come</td><td>Used with <code>tista&#39;</code> to mean “can come”</td></tr><tr><td>l-għassa</td><td>the station; police station</td><td>Feminine noun with the definite article</td></tr><tr><td>għada</td><td>tomorrow</td><td>Time adverb</td></tr><tr><td>filgħodu</td><td>in the morning</td><td>Time expression</td></tr></tbody></table><h3 id="_5-anna-owner-of-the-lost-item" tabindex="-1">5. Anna (Owner of the Lost Item) <a class="header-anchor" href="#_5-anna-owner-of-the-lost-item" aria-label="Permalink to &quot;5. Anna (Owner of the Lost Item)&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; niġi fid-disgħa?</p><p><strong>Translation:</strong> Can I come at nine?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>can I?</td><td>First-person singular form</td></tr><tr><td>niġi</td><td>I come</td><td>First-person singular form</td></tr><tr><td>fid-disgħa</td><td>at nine</td><td>Contracted <code>f&#39;</code> “at” + <code>id-disgħa</code> “nine o&#39;clock”</td></tr></tbody></table><h3 id="_6-mark-police-officer" tabindex="-1">6. Mark (Police Officer) <a class="header-anchor" href="#_6-mark-police-officer" aria-label="Permalink to &quot;6. Mark (Police Officer)&quot;">​</a></h3><p><strong>Malti:</strong> Iva. Ġib miegħek dokument ta&#39; identità.</p><p><strong>Translation:</strong> Yes. Bring an identity document with you.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Iva</td><td>yes; all right</td><td>Affirmative response</td></tr><tr><td>Ġib</td><td>bring</td><td>Singular imperative</td></tr><tr><td>miegħek</td><td>with you; along with you</td><td><code>miegħ</code> “with” + <code>-ek</code> “you”</td></tr><tr><td>dokument</td><td>document; identification</td><td>Masculine noun</td></tr><tr><td>ta&#39;</td><td>of</td><td>Connects nouns to show type or possession</td></tr><tr><td>identità</td><td>identity</td><td>Feminine noun</td></tr></tbody></table><h3 id="_7-anna-owner-of-the-lost-item" tabindex="-1">7. Anna (Owner of the Lost Item) <a class="header-anchor" href="#_7-anna-owner-of-the-lost-item" aria-label="Permalink to &quot;7. Anna (Owner of the Lost Item)&quot;">​</a></h3><p><strong>Malti:</strong> Se jkolli bżonn inġib xi prova oħra?</p><p><strong>Translation:</strong> Will I need to bring any other proof?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Se</td><td>will</td><td>Common future marker</td></tr><tr><td>jkolli</td><td>I will have; I will need</td><td>One future form of <code>għandi</code></td></tr><tr><td>bżonn</td><td>need</td><td><code>ikolli bżonn</code> means “I need”</td></tr><tr><td>inġib</td><td>I bring</td><td>First-person singular form</td></tr><tr><td>xi</td><td>some; any</td><td>Means “any other” here</td></tr><tr><td>prova</td><td>proof; evidence</td><td>Feminine noun</td></tr><tr><td>oħra</td><td>other</td><td>Feminine form agreeing with <code>prova</code></td></tr></tbody></table><h3 id="_8-mark-police-officer" tabindex="-1">8. Mark (Police Officer) <a class="header-anchor" href="#_8-mark-police-officer" aria-label="Permalink to &quot;8. Mark (Police Officer)&quot;">​</a></h3><p><strong>Malti:</strong> Le, id-dokument tal-identità jkun biżżejjed.</p><p><strong>Translation:</strong> No, the identity document will be enough.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Le</td><td>no</td><td>Negative response</td></tr><tr><td>id-dokument</td><td>the document</td><td>Definite article written with the noun</td></tr><tr><td>tal-identità</td><td>of identity; identity</td><td>Contracted <code>ta&#39; + l-identità</code></td></tr><tr><td>jkun</td><td>will be; may be</td><td>Subjunctive/subordinate form of <code>ikun</code></td></tr><tr><td>biżżejjed</td><td>enough; sufficient</td><td>Fixed adjective/adverb expression</td></tr></tbody></table><h2 id="additional-vocabulary" tabindex="-1">Additional Vocabulary <a class="header-anchor" href="#additional-vocabulary" aria-label="Permalink to &quot;Additional Vocabulary&quot;">​</a></h2><ul><li><code>uffiċċju tal-pulizija</code>: police office.</li><li><code>rapport</code>: report; incident report.</li><li><code>Tlift il-kartiera tiegħi.</code>: I lost my wallet.</li><li>Actual procedures for collecting lost property vary by station and item; this dialogue is for language practice.</li></ul>',46),i=[r];function n(l,s,c,h,f,p){return e(),a("div",null,i)}const u=t(d,[["render",n]]);export{g as __pageData,u as default};
